# Generated by 'mynotes service install'; runs the mynotes worker at logon.
[Environment]::SetEnvironmentVariable('MYNOTES_CONFIG', 'C:\Users\test\mynotes.yaml', 'User')
[Environment]::SetEnvironmentVariable('MYNOTES_LOG_FILE', 'C:\Users\test\AppData\Local\mynotes\Logs/worker.log', 'User')
$action = New-ScheduledTaskAction -Execute 'C:\proj\.venv\Scripts\pythonw.exe' -Argument '-m mynotes worker' -WorkingDirectory 'C:\proj'
$trigger = New-ScheduledTaskTrigger -AtLogOn
$settings = New-ScheduledTaskSettingsSet -RestartCount 3 -RestartInterval (New-TimeSpan -Minutes 1) -ExecutionTimeLimit 0
Register-ScheduledTask -TaskName 'mynotes-worker' -Action $action -Trigger $trigger -Settings $settings
